    List<Aggregator> aggregators = new ArrayList<>();
    aggregationDescriptors.forEach(o -> aggregators.add(new Aggregator(AccumulatorFactory.createBuiltinAccumulator(o.getAggregationType(), Collections.singletonList(measurementPath.getSeriesType()), Collections.emptyList(), Collections.emptyMap(), true), o.getStep())));
